cd /work && python3 -c "
import csv,warnings; warnings.filterwarnings('ignore')
from pymatgen.core import Structure
r={x['candidate_id']:x for x in csv.DictReader(open('nlo_pool.csv'))}
for k in ['c073','c066','c048','c072','c070','c065','c055','c020']:
    s=Structure.from_str(r[k]['poscar'],fmt='poscar')
    print('===',k,r[k]['formula'])
    for i,site in enumerate(s):
        nb=s.get_neighbors(site,3.3)
        print(' ',site.specie, len(nb), sorted(f'{n.specie}{n.nn_distance:.2f}' for n in nb))
"

